package holamundo;

public class OperadoresRelacionales {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		        
		        // Igual que ==
		        System.out.println("El resultado de comparar 5 == 4 es: " + (5 == 4));

		        // Diferente que !=
		        System.out.println("El resultado de comparar 4 != 2 es: " + (4 != 2));

		        // Menor que <
		        System.out.println("El resultado de comparar 5 < 2 es: " + (5 < 2));

		        // Mayor que >
		        System.out.println("El resultado de comparar 5 > -5 es: " + (5 > -5));

		        // Menor o igual que <=
		        System.out.println("El resultado de comparar 2 <= 3 es: " + (2 <= 3));

		        // Mayor o igual que >=
		        System.out.println("El resultado de comparar 3 >= 9 es: " + (3 >= 9));	
			
		
	}

}
